text:
What is the output of the following C code?

int a = 5;
int b = a;
a = 15;
printf("%d %d", a, b);

What is the output of the following C code demonstrating block scope?

int main(void) {
    int x = 10;
    {
        int x = 20;
        printf("%d ", x);
    }
    printf("%d", x);
    return 0;
}

What is the output of the following C code?

#include <stdio.h>

void step(void) {
    static int n = 2;
    n *= 2;
    printf("%d ", n);
}

int main(void) {
    step();
    step();
    return 0;
}

What issue occurs in the following C code?

int main(void) {
    const int MAX = 100;
    MAX = 200;
    printf("%d", MAX);
    return 0;
}

What is the result of compiling the following C code?

int a = 5;

void func(void) {
    static int b = a;
    printf("%d", b);
}

What is the output of the following standard C code?

#include <stdio.h>

int main(void) {
    int diff = '3' - '0';
    printf("%d", diff);
    return 0;
}

What is the output of the following C code?

int x = 2, y = 3, z;
z = x + y * x;
printf("%d", z);

Which keyword should fill in the blank so that RATE cannot be modified through ordinary assignment after its initialization?

______ float RATE = 0.05f;
RATE = 0.10f;

What issue occurs in the following C code?

#include <stdio.h>

void test(void) {
    register int num = 10;
    int *ptr = &num;
    printf("%d", *ptr);
}

What is the output of the following C code?

#include <stdio.h>

int main(void) {
    int a = 5;
    float b = 2.0f;
    float result = a / b;
    printf("%.1f", result);
    return 0;
}

What is the output of the following C99 code?

#include <stdio.h>

int main(void) {
    int i = 100;
    for (int i = 0; i < 3; i++) {
    }
    printf("%d", i);
    return 0;
}

Which keyword gives the following file-scope object internal linkage?

______ int internal_counter = 0;

void increment(void) {
    internal_counter++;
}

Why does the following C code violate a constraint?

int main(void) {
    char word[] = "cat";
    word = "dog";
    printf("%s", word);
    return 0;
}

What is the output of the following valid C program?

#include <stdio.h>

int val;
int val;
int val = 42;

int main(void) {
    printf("%d", val);
    return 0;
}

What issue occurs in the following C code?

void test(int x) {
    int x = 50;
    printf("%d", x);
}

What is the output of the following valid C99 code using a compound literal?

#include <stdio.h>

int main(void) {
    int *p = (int[]){10, 20, 30};
    p[0] += 5;
    p[2] = p[0] + p[1];
    printf("%d %d", p[0], p[2]);
    return 0;
}

What is the output of the following C code on a conforming implementation?

#include <stdio.h>

int main(void) {
    int a = -5;
    unsigned int b = 3;
    if (a + b > 0) {
        printf("Greater");
    } else {
        printf("Less or Equal");
    }
    return 0;
}

What is the output of the following C code?

int a = 14, b = 4;
printf("%d %d", a / b, a % b);

What is the output of the following C code?

int x = 5, y = 10;
int res = !(x < y);
printf("%d", res);

What is the output of the following C code?

int a = 5, b = 5;
int x = a++;
int y = ++b;
printf("%d %d", x, y);

What is the output of the following C code involving bitwise operators?

int a = 6, b = 3;
printf("%d %d", a & b, a | b);

What is the output of the following C code?

int a = 0, b = 5;
if (a != 0 && ++b > 5) {
    b += 2;
}
printf("%d", b);

What is the output of the following C code using nested conditional operators?

int a = 1, b = 2, c = 3;
int res = a > b ? a : b > c ? b : c;
printf("%d", res);

What is the output of the following C code using the comma operator?

int x = 5, y = 10;
int z = (x += 2, y += x, y);
printf("%d %d %d", x, y, z);

What is the output of the following C code testing operator precedence?

int a = 1, b = 2, c = 3;
int res = a < b == c;
printf("%d", res);

What is the output of the following C code?

#include <stdio.h>
#include <stddef.h>

int main(void) {
    int x = 5;
    size_t s = sizeof(++x);
    printf("%d", x);
    return 0;
}

What is the output of the following C code?

int x = 1 << 2 + 1;
printf("%d", x);

What is the output of the following C code demonstrating right-to-left assignment associativity?

int a, b, c;
a = b = c = 7;
a += b += c;
printf("%d %d %d", a, b, c);

What is the output of the following C code utilizing bitwise XOR properties?

int x = 25;
int res = (x ^ x) + (x ^ 0);
printf("%d", res);

What is the output of the following C code demonstrating explicit type-cast placement?

double val1 = (double)5 / 2;
double val2 = (double)(5 / 2);
printf("%.1f %.1f", val1, val2);

What happens when compiling the following C code?

float x = 7.5f;
int y = 2;
int rem = (int)x % y;
printf("%d", rem);

What is the output of the following C code testing logical OR short-circuit evaluation?

int a = 1, b = 4;
if (a == 1 || ++b > 4) {
    b += 2;
}
printf("%d", b);

What is the output of the following C code involving bitwise NOT?

#include <stdio.h>

int main(void) {
    unsigned int x = 0x0Fu;
    unsigned int y = (~x) & 0xFFu;
    printf("%u", y);
    return 0;
}

Which expression checks whether the third bit (zero-indexed, representing the value 8) of flags is set?

int is_set = ______;
if (is_set) printf("Bit is ON");

What is the output of the following C code involving compound assignment and conversion to int?

int x = 5;
x *= 1.8;
printf("%d", x);

What is the output of the following C code containing an assignment inside an if condition?

int x = 10;
if (x = 0) {
    printf("Yes %d", x);
} else {
    printf("No %d", x);
}

What is the output of the following C code demonstrating member access through a pointer and prefix increment?

#include <stdio.h>

struct Pair { int a; int b; };

int main(void) {
    struct Pair p = {10, 20};
    struct Pair *ptr = &p;
    int res = ++ptr->a;
    printf("%d %d", res, ptr->a);
    return 0;
}

What is the output of the following C code?

int a = 0, b = 2;
int res = !a && b;
printf("%d", res);

What is the output of the following C code?

#include <stdio.h>
#include <stddef.h>

int main(void) {
    int condition = 1;
    size_t res = sizeof(condition ? 10 : 2.5f);
    printf("%d", res == sizeof(float));
    return 0;
}

What is the output of the following C code combining pointer dereference with prefix decrement?

int arr[] = {10, 20, 30};
int *p = &arr[2];
int val = *--p;
printf("%d %d", val, *p);

What is the output of the following C code performing bitwise shifts and masking?

unsigned int x = 0xF0;
unsigned int res = ((x >> 4) | (x << 4)) & 0xFF;
printf("%u", res);

What is the output of the following C code involving short-circuit evaluation inside a conditional expression?

int x = 0, y = 1;
int z = (x++ && ++y) ? 100 : (x + y);
printf("%d", z);

What is the output of the following C code?

int score = 75;
if (score >= 90)
    printf("A");
else if (score >= 70)
    printf("B");
else
    printf("C");

What is the output of the following C code?

int i = 3;
while (i > 0) {
    printf("%d", i);
    i--;
}

What is the output of the following C code?

int x = 10;
do {
    x += 5;
} while (x < 10);
printf("%d", x);

What is the output of the following C code?

int count = 0;
for (int i = 0; i < 5; i += 2) {
    count++;
}
printf("%d", count);

What is the output of the following C code?

int x = 2;
switch (x) {
    case 1: printf("A");
    case 2: printf("B");
    case 3: printf("C");
    default: printf("D");
}

What is the output of the following C code?

int sum = 0;
for (int i = 1; i <= 5; i++) {
    if (i % 2 == 0)
        continue;
    sum += i;
}
printf("%d", sum);

What is the output of the following C code?

int count = 0;
for (int i = 0; i < 3; i++) {
    for (int j = 0; j < 3; j++) {
        if (j == 1)
            break;
        count++;
    }
}
printf("%d", count);

What is the output of the following C code demonstrating the dangling-else rule?

int a = 1, b = 0;
if (a > 0)
    if (b > 0)
        printf("One");
    else
        printf("Two");

What is the output of the following C code?

int x = 5;
switch (x) {
    default: x += 2;
    case 1: x += 3; break;
    case 2: x += 4; break;
}
printf("%d", x);

What is the output of the following C code using the comma operator in a for-loop condition?

int count = 0;
for (int i = 0, j = 0; i < 3, j < 5; i++, j++) {
    count++;
}
printf("%d", count);

What is the output of the following C code?

int x = -5;
if (x) {
    printf("True");
} else {
    printf("False");
}

Why does the following C code fail to compile?

int x = 1;
do {
    x++;
} while (x < 5)
printf("%d", x);

What is the output of the following C code using stacked case labels?

int code = 2;
switch (code) {
    case 1:
    case 2:
    case 3:
        printf("Valid ");
        break;
    default:
        printf("Invalid ");
}

Which keyword must fill the blank so that the loop prints exactly 0123?

for (int i = 0; i < 10; i++) {
    if (i == 4)
        ______;
    printf("%d", i);
}

What is the output of the following C code?

int x = 0;
if (x > 0);
{
    x = 10;
}
printf("%d", x);

What happens when compiling the following C code?

int x = 2;
switch (x) {
    case 1: printf("One"); break;
    case 2: printf("Two"); break;
    case 1 + 1: printf("Duplicate"); break;
}

What is the output of the following C code with an omitted for-loop condition?

int count = 0;
for (int i = 0; ; i++) {
    if (i >= 3)
        break;
    count += i;
}
printf("%d", count);

What is the output of the following C code?

int test(void) {
    for (int i = 1; i <= 5; i++) {
        if (i == 3)
            return i * 10;
    }
    return 0;
}

// In main:
printf("%d", test());

What is the output of the following C code?

int n = 3;
while (--n) {
    printf("%d ", n);
}

What is the output of the following C code demonstrating break inside a nested switch statement?

int sum = 0;
for (int i = 1; i <= 2; i++) {
    switch (i) {
        case 1: sum += 10; break;
        case 2: sum += 20; break;
    }
    sum += 1;
}
printf("%d", sum);

What is the result of compiling this C99 code?

for (int i = 0, double d = 0.0; i < 5; i++) {
    printf("%d ", i);
}

What is the problem with the following C code when execution reaches case 2?

int x = 2;
switch (x) {
    int y = 10;
    case 1: printf("%d", y); break;
    case 2: printf("%d", y); break;
}

What is the output of the following valid C code?

int n = 2, val = 0;
switch (n) {
    do {
        case 1: val += 10;
        case 2: val += 20;
    } while (0);
}
printf("%d", val);

What is the output of the following C code?

int k = 0;
for (int i = 0; i < 3; i++) {
    for (int j = 0; j < 3; j++) {
        if (i == j)
            continue;
        k++;
    }
}
printf("%d", k);

What is the output of the following C code demonstrating goto to exit nested loops?

int count = 0;
for (int i = 0; i < 3; i++) {
    for (int j = 0; j < 3; j++) {
        if (i == 1 && j == 1)
            goto done;
        count++;
    }
}
done:
printf("%d", count);

What is the output of the following C code?

int x = 1, y = 10;
switch (x) {
    case 1:
        y += 5;
    case 2: {
        int z = y * 2;
        y = z - 5;
        break;
    }
    default:
        y = 0;
}
printf("%d", y);

What is the output of the following C code?

int sum = 0;
for (int i = 1; i <= 4; i++) {
    sum += i;
}
printf("%d", sum);

What is the result of compiling and running the following C99 code?

for (int i = 0; i < 3; i++) {
}
printf("%d", i);

What is the output of the following C code containing a trailing semicolon after the loop header?

int i;
for (i = 0; i < 4; i++);
printf("%d", i);

What is the output of the following nested loop in C?

int total = 0;
for (int i = 1; i <= 2; i++) {
    for (int j = 1; j <= 3; j++) {
        total += i * j;
    }
}
printf("%d", total);

What is the output of the following C code?

int count = 0, n = 0;
while (n < 5) {
    n++;
    if (n == 3)
        continue;
    count++;
}
printf("%d", count);

What is the output of the following C code?

int x = 0;
while (x++ < 3) {
    printf("%d", x);
}

What behavior occurs when executing the following C loop?

for (unsigned int i = 3; i >= 0; i--) {
    printf("%u ", i);
}

What is the output of the following C code?

int a = 0, b = 10;
for (; a < b; a += 2, b -= 1) {
}
printf("%d %d", a, b);

What is the output of the following C code?

int x = 5;
while (x < 3) {
    x += 2;
}
printf("%d", x);

What is the output of the following C code with a decrementing loop counter?

for (int i = 8; i > 2; i -= 2) {
    printf("%d ", i);
}

What is the output of the following C code iterating over an array of characters?

char chars[] = {'A', 'B', 'C'};
for (int i = 0; i < 3; i++) {
    printf("%c", chars[i]);
}

Which update expression should fill in the blank to print the powers of two 1 2 4 8?

for (int i = 1; i <= 8; ______) {
    printf("%d ", i);
}

What is the output of the following nested loop in C?

int count = 0;
for (int i = 0; i < 4; i++) {
    for (int j = 0; j <= i; j++) {
        count++;
    }
}
printf("%d", count);

What happens when executing this C code?

int i = 0;
while (i < 3);
{
    i++;
}
printf("%d", i);

What behavior occurs when running the following C code?

int n = 0;
while (n < 4) {
    if (n == 2) continue;
    n++;
}
printf("%d", n);

What is the output of the following C code?

int x = 4;
while (--x > 0) {
    printf("%d ", x);
}

What is the output of the following C code involving a compound loop condition?

int sum = 0;
for (int i = 0; i < 5 && i != 3; i++) {
    sum += i;
}
printf("%d", sum);

What is the output of the following C code where the loop counter is altered within the loop body?

int count = 0;
for (int i = 0; i < 10; i++) {
    if (i == 2) i += 3;
    count++;
}
printf("%d", count);

What is the output of the following C code containing a side effect in the loop update expression?

int i = 1;
for (; i <= 3; printf("%d", i++)) {
    printf("");
}

What is the output of the following C code traversing a null-terminated string?

char str[] = "Test";
char *p = str;
int count = 0;
while (*p++) {
    count++;
}
printf("%d", count);

What occurs when attempting to compile the following C code?

do {
    int val = 5;
    val--;
} while (val > 0);

What is the output of the following nested C loop where the inner loop modifies the outer loop counter?

int steps = 0;
for (int i = 0; i < 3; i++) {
    for (int j = 0; j < 2; j++) {
        i++;
        steps++;
    }
}
printf("%d", steps);

What is the output of the following C code combining continue and break?

int sum = 0;
for (int i = 1; i <= 6; i++) {
    if (i % 3 == 0) continue;
    if (i > 4) break;
    sum += i;
}
printf("%d", sum);

What is the output of the following C code demonstrating parameter passing?

void modify(int x) {
    x = 20;
}

int main(void) {
    int a = 10;
    modify(a);
    printf("%d", a);
    return 0;
}

What is the output of the following recursive C function?

int fact(int n) {
    if (n <= 1)
        return 1;
    return n * fact(n - 1);
}

int main(void) {
    printf("%d", fact(4));
    return 0;
}

What is the output of the following C code?

void alter(int arr[]) {
    arr[0] = 99;
}

int main(void) {
    int nums[] = {1, 2, 3};
    alter(nums);
    printf("%d", nums[0]);
    return 0;
}

What is the output of the following recursive C code?

int calc(int n) {
    if (n == 0)
        return 0;
    return n + calc(n - 2);
}

int main(void) {
    printf("%d", calc(6));
    return 0;
}

What is the output of the following C code involving a function pointer?

int add(int a, int b) {
    return a + b;
}

int sub(int a, int b) {
    return a - b;
}

int main(void) {
    int (*op)(int, int) = add;
    op = sub;
    printf("%d", op(10, 4));
    return 0;
}

What is the output of the following C code demonstrating pass-by-value semantics with a structure?

struct Point { int x, y; };

void reset(struct Point p) {
    p.x = 0;
    p.y = 0;
}

int main(void) {
    struct Point pt = {10, 20};
    reset(pt);
    printf("%d %d", pt.x, pt.y);
    return 0;
}

In C99 and newer standards, what happens if execution reaches the closing brace of 'main' without encountering an explicit return statement?

int main(void) {
    printf("Complete");
}

Which keyword should fill in the blank to prevent the function from modifying the characters through the pointer 'str'?

void display(______ char *str) {
    printf("%s", str);
}

What is the output of the following C code involving a callback function?

int square(int x) {
    return x * x;
}

int apply(int (*fn)(int), int val) {
    return fn(val) + 1;
}

int main(void) {
    printf("%d", apply(square, 3));
    return 0;
}

What is the critical bug in the following C function?

int *get_number(void) {
    int val = 42;
    return &val;
}

What is the output of the following C code containing a static local variable?

int track(void) {
    static int count = 5;
    return count += 2;
}

int main(void) {
    track();
    printf("%d", track());
    return 0;
}

What happens when compiling this code in standard C (C99/C11)?

void outer(void) {
    void inner(void) {
        printf("Inside");
    }
    inner();
}

What is the output of the following C code using a typedef for a function pointer?

typedef int (*MathFunc)(int, int);

int multiply(int a, int b) {
    return a * b;
}

int main(void) {
    MathFunc f = multiply;
    printf("%d", f(4, 5));
    return 0;
}

What is the output of the following C code?

void update_ptr(int **p, int *new_val) {
    *p = new_val;
}

int main(void) {
    int a = 10, b = 20;
    int *ptr = &a;
    update_ptr(&ptr, &b);
    printf("%d", *ptr);
    return 0;
}

What is the output of the following C code utilizing an array of function pointers?

int add(int a) { return a + 1; }
int dbl(int a) { return a * 2; }
int sub(int a) { return a - 1; }

int main(void) {
    int (*table[3])(int) = {add, dbl, sub};
    printf("%d", table[1](4));
    return 0;
}

What is the output of the following variadic C function?

#include <stdarg.h>

int sum(int n, ...) {
    va_list ap;
    va_start(ap, n);
    int s = 0;
    for (int i = 0; i < n; i++) {
        s += va_arg(ap, int);
    }
    va_end(ap);
    return s;
}

int main(void) {
    printf("%d", sum(3, 10, 20, 30));
    return 0;
}

Why is the function call 'print_pair(i++, i++);' hazardous in standard C?

void print_pair(int a, int b) {
    printf("%d %d", a, b);
}

int main(void) {
    int i = 1;
    print_pair(i++, i++);
    return 0;
}

What is the output of the following C code demonstrating a function that returns a function pointer?

typedef int (*Func)(int);

int step(int x) {
    return x + 5;
}

Func get_func(void) {
    return step;
}

int main(void) {
    printf("%d", get_func()(10));
    return 0;
}

What is the output of the following C code?

int numbers[4] = {10, 20, 30, 40};
numbers[1] = 50;
printf("%d", numbers[1]);

What is the output of the following C code with partial initialization?

int arr[5] = {1, 2};
printf("%d %d", arr[2], arr[4]);

What is the output of the following C code?

#include <stdio.h>
#include <stddef.h>

int main(void) {
    int arr[] = {3, 7, 1, 9, 4, 6};
    size_t n = sizeof(arr) / sizeof(arr[0]);
    printf("%zu", n);
    return 0;
}

What is the output of the following C code?

int matrix[2][3] = {
    {1, 2, 3},
    {4, 5, 6}
};
printf("%d", matrix[1][0]);

What is the output of the following C code?

int arr[] = {10, 20, 30, 40};
printf("%d", 2[arr]);

What happens when attempting to compile the following C code?

int a[3] = {1, 2, 3};
int b[3] = {4, 5, 6};
a = b;

What is the output of the following C99 code utilizing designated initializers?

int arr[6] = {[1] = 5, [4] = 9};
printf("%d %d %d", arr[0], arr[1], arr[2]);

What is the output of the following C code involving row-major initialization?

int grid[2][3] = {1, 2, 3, 4, 5, 6};
printf("%d %d", grid[0][2], grid[1][1]);

What is the output of the following C99 code involving a variable-length array (VLA)?

int main(void) {
    int n = 3;
    int arr[n];
    n = 5;
    printf("%zu", sizeof(arr) / sizeof(arr[0]));
    return 0;
}

What is the output of the following C code?

int arr[] = {10, 20, 30, 40};
int count = sizeof(arr) / sizeof(int);
printf("%d", count);

What is the result of attempting to compile this C code?

const int numbers[3] = {1, 2, 3};
numbers[1] = 10;
printf("%d", numbers[1]);

What is the output of the following C code?

int arr[4] = {5, 10, 15, 20};
int *p = arr;
printf("%d", *(p + 2));

What is the output of the following C code using pointer indexing?

int arr[] = {10, 20, 30, 40, 50};
int *p = &arr[3];
printf("%d", p[-2]);

When 'print_size' is called with an array of 10 integers, why does 'sizeof(arr)' not evaluate to '10 * sizeof(int)'?

void print_size(int arr[10]) {
    printf("%zu", sizeof(arr));
}

What is the output of the following C code accessing a three-dimensional array?

int tensor[2][2][2] = {
    {{1, 2}, {3, 4}},
    {{5, 6}, {7, 8}}
};
printf("%d", tensor[1][0][1]);

What is the output of the following C code involving an array of pointers?

int a = 1, b = 2, c = 3;
int *ptrs[] = {&a, &b, &c};
*ptrs[1] += 10;
printf("%d %d", b, *ptrs[1]);

What is the output of the following C99 code utilizing designated initializers on a two-dimensional array?

